# ===== restore adapters =====
print("== adapters ==", flush=True)
need = [f"s{i}/{d}" for i in "012" for d in ["full", "retain90", "ctrl_distill", "oraclehi"]]
for d in need:
    os.makedirs(f"/content/adapters/{d.split('/')[0]}", exist_ok=True)
    subprocess.run(f'cp -r "/content/drive/MyDrive/tofu_v3_backup/adapters/{d}" "/content/adapters/{d}" 2>/dev/null', shell=True)
subprocess.run("ls /content/adapters/s0/", shell=True)
# restore finished v11 results so completed stages skip themselves after a VM recycle
subprocess.run('mkdir -p /content/results_v11 && cp -r "/content/drive/MyDrive/tofu_v3_backup/results_v11/." /content/results_v11/ 2>/dev/null; ls /content/results_v11/', shell=True)


# ===== load the library =====
print("== library ==", flush=True)
import sys
os.chdir("/content")
for f in ["tofu_all.py", "tofu_v3.py", "tofu_v4.py", "tofu_v5.py",
          "tofu_v6.py", "tofu_v7.py", "tofu_v8.py", "tofu_v9.py"]:
    print("loading", f, flush=True)
    sys.argv = [f]
    exec(open(f).read())
print("library loaded")


# ===== backup() =====
def backup():
    subprocess.run(["bash", "-c",
      "mkdir -p '/content/drive/MyDrive/tofu_v3_backup/results_v11' && "
      "mkdir -p '/content/drive/MyDrive/tofu_v3_backup/adapters_v11' && "
      "cp -r results_v11/. '/content/drive/MyDrive/tofu_v3_backup/results_v11/' 2>/dev/null; "
      "for s in 0 1 2; do for d in ctrl_distill oraclehi; do "
      "  if [ -d adapters/s$s/$d ]; then mkdir -p '/content/drive/MyDrive/tofu_v3_backup/adapters/s'$s; "
      "  cp -r adapters/s$s/$d '/content/drive/MyDrive/tofu_v3_backup/adapters/s'$s'/' ; fi; done; done; true"])
    print("backed up results_v11 (and new adapters) to Drive")


# ===== driver (~2.5-3.5 h) =====
STAGES = ([("distillctrl", s) for s in "012"] + [("oraclehi", s) for s in "12"])
for stage, seed in STAGES:
    print(f"\n===== v11 {stage} {seed} =====", flush=True)
    sys.argv = ["tofu_v11.py", stage, seed]
    exec(open("tofu_v11.py").read())
    backup()
sys.argv = ["tofu_v11.py", "figures11"]; exec(open("tofu_v11.py").read())
print("V11 COMPLETE")


# ===== zip to Drive =====
subprocess.run("cd /content && zip -qr results_v11.zip results_v11", shell=True)
subprocess.run('cp /content/results_v11.zip "/content/drive/MyDrive/"', shell=True)
print("results_v11.zip is in MyDrive -- download it into the Persistence of Memory folder")
